<script setup>
import { ref, watch, onMounted } from 'vue'
const section=ref('characters'), characters=ref([]), jokes=ref([]), activities=ref([]), busy=ref({}), errors=ref({}), query=ref({characters:'',jokes:'',activities:''}), filters=ref({characters:'all',jokes:'Any',activities:'all'}), pages=ref({characters:1}), selected=ref(null), menu=ref(false)
const characterStatuses=['all','alive','dead','unknown'], jokeCategories=['Any','Programming','Misc','Pun','Spooky','Christmas'], activityTypes=['all','education','recreational','social','diy','charity','cooking','relaxation','music','busywork']
const descriptions={characters:'Meet the weird and wonderful residents of the multiverse.',jokes:'A little laughter goes a long way. Find your kind of funny.',activities:'Your next great idea is just one click away.'}
async function load(key) {
 busy.value={...busy.value,[key]:true};errors.value={...errors.value,[key]:''}
 try {
  const url=new URL('/api/'+key,location.origin)
  if(query.value[key]) url.searchParams.set('search',query.value[key])
  if(filters.value[key]!=='all'&&filters.value[key]!=='Any') url.searchParams.set('type',filters.value[key])
  if(key==='characters'){url.searchParams.set('status',filters.value.characters);url.searchParams.set('page',pages.value.characters)}
  const res=await fetch(url)
  const data=await res.json()
  if(!res.ok)throw Error(data.error||'Could not load content.')
  const value=key==='characters'?(data.results||[]):key==='jokes'?(data.jokes||[]):(data.activities||[])
  if(key==='characters')characters.value=value
  if(key==='jokes')jokes.value=value
  if(key==='activities')activities.value=value
 }catch(err){errors.value={...errors.value,[key]:err.message}}
 finally{busy.value={...busy.value,[key]:false}}
}
let timers={}
function search(key){clearTimeout(timers[key]);pages.value.characters=1;timers[key]=setTimeout(()=>load(key),350)}
function filter(key,v){filters.value[key]=v;pages.value.characters=1;load(key)}
function go(id){section.value=id;menu.value=false;document.getElementById(id)?.scrollIntoView({behavior:'smooth'})}
onMounted(()=>{load('characters');load('jokes');load('activities')})
</script>
<template>
<div class="site" id="top">
 <div class="ambient ambient-one"></div><div class="ambient ambient-two"></div>
 <header class="header shell"><a class="brand" href="#top"><span class="brand-mark">✳</span><span>VANTA <b>FUN</b></span></a><nav :class="{open:menu}"><a href="#characters" @click="menu=false">Characters</a><a href="#jokes" @click="menu=false">Jokes</a><a href="#activities" @click="menu=false">Activities</a></nav><button class="nav-cta" @click="go('characters')">Explore the fun <span>↗</span></button><button class="hamburger" aria-label="Toggle navigation" @click="menu=!menu">☰</button></header>
 <main>
  <section class="hero shell"><div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span> YOUR DAILY DOSE OF DISCOVERY <span class="tiny-star">✦</span></div><h1>Bored?<br><em>Not here<span class="period">.</span></em></h1><p>Explore the multiverse. Discover your next favourite joke. Find something exciting to do. All the fun, in one place.</p><div class="hero-actions"><button class="primary-btn" @click="go('characters')">Start exploring <span>↗</span></button><a href="#about" class="quiet-link">What is Vanta Fun? <span>↓</span></a></div><div class="hero-stats"><div><strong>03</strong><span>INTERACTIVE WORLDS</span></div><div><strong>∞</strong><span>POSSIBILITIES</span></div><div><strong>100%</strong><span>CURIOSITY</span></div></div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="hero-center"><span>✳</span><small>THE FUN STARTS HERE</small></div><div class="float-card float-one"><span>👽</span><small>CHARACTERS</small></div><div class="float-card float-two"><span>😂</span><small>JOKES</small></div><div class="float-card float-three"><span>🎨</span><small>ACTIVITIES</small></div><div class="spark spark-a">✦</div><div class="spark spark-b">✳</div></div></section>
  <div class="ticker"><div>THREE WORLDS <span>✳</span> INFINITE FUN <span>✳</span> NEVER A DULL MOMENT <span>✳</span> THREE WORLDS <span>✳</span> INFINITE FUN <span>✳</span> NEVER A DULL MOMENT <span>✳</span></div></div>
  <section id="characters" class="content-section shell purple"><div class="section-top"><div><div class="section-kicker"><span>01 / THE MULTIVERSE</span></div><h2>Meet the <em>characters.</em></h2><p>{{ descriptions.characters }}</p></div><span class="section-icon">👾</span></div><div class="toolbar"><label class="search"><span>⌕</span><input v-model="query.characters" placeholder="Search characters..." @input="search('characters')"></label><div class="chips"><button v-for="status in characterStatuses" :key="status" :class="{active:filters.characters===status}" @click="filter('characters',status)">{{status}}</button></div></div><p v-if="busy.characters" class="notice">Loading characters...</p><div v-if="errors.characters" class="notice error">{{errors.characters}} <button @click="load('characters')">Try again ↻</button></div><div v-if="!busy.characters" class="cards character-grid"><button v-for="c in characters" :key="c.id" class="content-card character-card" @click="selected={kind:'character',...c}"><img :src="c.image" :alt="c.name" loading="lazy"><div class="card-content"><span class="card-meta"><i :class="(c.status||'').toLowerCase()"></i>{{c.status||'Unknown'}} · {{c.species||'Unknown'}}</span><h3>{{c.name}}</h3><span class="card-link">View profile ↗</span></div></button></div><div class="section-actions"><button class="secondary-btn" :disabled="pages.characters<=1||busy.characters" @click="pages.characters--;load('characters')">← Previous</button><span>PAGE {{pages.characters}}</span><button class="secondary-btn" :disabled="busy.characters||characters.length<12" @click="pages.characters++;load('characters')">Next →</button></div></section>
  <section id="jokes" class="content-section shell yellow"><div class="section-top"><div><div class="section-kicker">02 / LAUGH A LITTLE</div><h2>Life's better <em>with laughs.</em></h2><p>{{descriptions.jokes}}</p></div><span class="section-icon">😆</span></div><div class="toolbar"><label class="search"><span>⌕</span><input v-model="query.jokes" placeholder="Search jokes..." @input="search('jokes')"></label><div class="chips"><button v-for="cat in jokeCategories" :key="cat" :class="{active:filters.jokes===cat}" @click="filter('jokes',cat)">{{cat}}</button></div></div><p v-if="busy.jokes" class="notice">Finding something funny...</p><div v-if="errors.jokes" class="notice error">{{errors.jokes}} <button @click="load('jokes')">Try again ↻</button></div><div class="cards joke-grid"><article v-for="(j,i) in jokes" :key="j.id||i" class="content-card joke-card"><div class="card-meta">{{j.category||'Joke'}} <span>✳</span></div><h3>{{j.type==='twopart'?j.setup:j.joke}}</h3><p v-if="j.type==='twopart'" class="punchline">{{j.delivery}}</p><div class="joke-bottom"><span>GOOD VIBES ONLY</span><button @click="navigator?.clipboard?.writeText?.(j.joke||(j.setup+' '+j.delivery))" class="copy-btn" title="Copy joke">↗</button></div></article></div><div class="section-actions"><button class="primary-btn yellow-btn" @click="load('jokes')">Shuffle the laughs ↻</button></div></section>
  <section id="activities" class="content-section shell blue"><div class="section-top"><div><div class="section-kicker">03 / MAKE A MEMORY</div><h2>Go do <em>something.</em></h2><p>{{descriptions.activities}}</p></div><span class="section-icon">⚡</span></div><div class="toolbar"><label class="search"><span>⌕</span><input v-model="query.activities" placeholder="Find an activity..." @input="search('activities')"></label><div class="chips"><button v-for="type in activityTypes" :key="type" :class="{active:filters.activities===type}" @click="filter('activities',type)">{{type}}</button></div></div><p v-if="busy.activities" class="notice">Finding inspiration...</p><div v-if="errors.activities" class="notice error">{{errors.activities}} <button @click="load('activities')">Try again ↻</button></div><div class="cards activity-grid"><article v-for="(a,i) in activities" :key="a.key||i" class="content-card activity-card"><div class="activity-number">{{String(i+1).padStart(2,'0')}}</div><span class="card-meta">{{a.type||'Activity'}}</span><h3>{{a.activity}}</h3><div class="activity-foot"><span>{{a.participants||1}} participant{{(a.participants||1)>1?'s':''}}</span><span>LET'S GO ↗</span></div></article></div><div class="section-actions"><button class="primary-btn blue-btn" @click="load('activities')">Surprise me ↻</button></div></section>
 </main><footer id="about" class="footer"><div class="shell footer-main"><div><div class="brand"><span class="brand-mark">✳</span>VANTA <b>FUN</b></div><h2>Fun looks good<br><em>on you.</em></h2><p>One page, three escapes. Built with Vue 3, powered by public APIs and curiosity.</p></div><div><h4>EXPLORE</h4><a href="#characters">Characters ↗</a><a href="#jokes">Jokes ↗</a><a href="#activities">Activities ↗</a></div><div><h4>DATA SOURCES</h4><a href="https://rickandmortyapi.com/" target="_blank" rel="noopener">Rick and Morty ↗</a><a href="https://v2.jokeapi.dev/" target="_blank" rel="noopener">JokeAPI ↗</a><a href="https://bored-api.appbrewery.com/" target="_blank" rel="noopener">Bored API ↗</a></div></div><div class="shell footer-bottom"><span>© {{new Date().getFullYear()}} VANTA FUN. Independent student project.</span><a href="#top">BACK TO TOP ↑</a></div></footer>
 <div v-if="selected" class="modal-backdrop" @click.self="selected=null"><div class="modal" role="dialog" aria-modal="true"><button class="modal-close" aria-label="Close" @click="selected=null">✕</button><img v-if="selected.image" :src="selected.image" :alt="selected.name"><div class="modal-body"><span class="section-kicker">CHARACTER PROFILE</span><h2>{{selected.name}}</h2><p>Status: {{selected.status}}</p><p>Species: {{selected.species}}</p><p>Origin: {{selected.origin?.name||'Unknown'}}</p><p>Location: {{selected.location?.name||'Unknown'}}</p></div></div></div>
</div>
</template>